import { parse } from '@babel/parser';
import traverse from '@babel/traverse';
import generate from '@babel/generator';

const ast = parse(code);                        // ① 파싱: 소스 → AST

traverse(ast, {                                 // ② 순회: 노드 타입별 방문
  CallExpression(path) {                        //   함수 호출 노드마다
    if (path.node.callee.name === 'getUser') {  // ③ 변형: 조건 맞으면
      path.node.callee.name = 'fetchUser';      //   이름을 바꾼다
    }
  }
});

const output = generate(ast).code;              // ④ 재출력: AST → 소스

traverse(ast, {
  CallExpression(path) {                        // ① 타입: 함수 호출만
    const callee = path.node.callee;
    // ② 이름·모양: getUser 라는 직접 호출 (a.getUser 아님)
    if (callee.type !== 'Identifier') return;   //   속성 접근 제외
    if (callee.name !== 'getUser') return;      //   다른 이름 제외
    // ③ 문맥·스코프: 이 getUser 가 우리가 아는 그 선언에 묶였나
    const binding = path.scope.getBinding('getUser');
    if (!binding || binding.path.node !== ourDeclaration) return;
    // ④ 여기까지 통과 = 진짜 그 노드 → 변형
    callee.name = 'fetchUser';
  }
});
